        vm.mockCall(
            ROUTER,
            abi.encodeWithSelector(IDEXRouter.WETH.selector),
            abi.encode(WBNB)
        );

        // Mock factory createPair
        vm.mockCall(
            factory,
            abi.encodeWithSelector(IDEXFactory.createPair.selector),
            abi.encode(pair)
        );

        // Deploy token as owner
        vm.prank(owner);
        token = new LionsLounge();
    }

    function testCanSetBuyFeesAboveLimit() public {
        // Check initial buy fee state
        console.log("\n--- [Buy] BEFORE FEE SETTING ---");
        uint256 initialTotalBuyFee = token.totalFeeBuy();
        console.log("Initial total buy fee: %s (denom: 100)", initialTotalBuyFee);

        // Execute buy fee change
        console.log("--- TRIGGER: setBuyFees(6,5,5,5,5,100) ---");
