        uint256 finalTotalBuyFee = token.totalFeeBuy();
        console.log("New total buy fee: %s (denom: 100)", finalTotalBuyFee);

        // Validate vulnerability existence
        if (finalTotalBuyFee > 25) {
            console.log("Vulnerability Exists: Buy fee set above 25%% (actual: %s%%)", finalTotalBuyFee);
        } else {
            console.log("Vulnerability not Exist: Buy fee within limits (actual: %s%%)", finalTotalBuyFee);
        }
    }

    function testCanSetSellFeesAboveLimit() public {
        // Check initial sell fee state
